extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale main.tscn deve caricarsi senza errori"):
		return
	var base := main.get_node_or_null("BlockBase") as Node3D
	if not check("base", base != null, "Nella scena serve un Node3D chiamato BlockBase figlio di Island"):
		return
	var top := main.get_node_or_null("BlockBase/BlockTop") as Node3D
	if not check("top", top != null, "BlockBase deve avere un figlio Node3D chiamato BlockTop"):
		return
	check("base_pos", base.position.is_equal_approx(Vector3(2.0, 0.0, -4.0)), "BlockBase deve avere posizione locale (2, 0, -4) (trovata: %s)" % str(base.position))
	check("top_pos", top.position.is_equal_approx(Vector3(0.0, 3.0, 0.0)), "BlockTop deve avere posizione locale (0, 3, 0) (trovata: %s)" % str(top.position))
	check("top_global", top.global_position.is_equal_approx(Vector3(2.0, 3.0, -4.0)), "La posizione globale di BlockTop deve essere (2, 3, -4) (trovata: %s)" % str(top.global_position))
